import { ref, computed, inject, provide, Teleport } from "vue"
import { JsonServiceClient } from "@servicestack/client"
import { useAuth, ModalDialog } from "@servicestack/vue"

// Minimal request DTO used by JsonServiceClient. This is the same request shape generated by
// ServiceStack's DTO generators, without requiring App Metadata or a page-specific DTO module.
class Authenticate {
    constructor(init) { Object.assign(this, init) }
    getTypeName() { return 'Authenticate' }
    getMethod() { return 'POST' }
    createResponse() { return {} }
}

const MetadataFreeSignIn = {
    name: 'MetadataFreeSignIn',
    emits: ['login'],
    template: `
        <div>
            <div class="text-center">
                <h2 class="text-2xl font-bold text-gray-900 dark:text-gray-50">Sign In</h2>
                <div v-if="formProviders.length > 1" class="mt-4 inline-flex rounded-md shadow-sm">
                    <button v-for="provider in formProviders" :key="provider.name" type="button"
                            @click="select(provider)"
                            :class="[selected?.name === provider.name
                                ? 'z-10 border-indigo-500 ring-1 ring-indigo-500'
                                : 'border-gray-300 dark:border-gray-600',
                                'relative -ml-px first:ml-0 first:rounded-l-md last:rounded-r-md border bg-white dark:bg-gray-950 px-4 py-1 text-sm text-gray-700 dark:text-gray-200']">
                        {{ labelOf(provider) }}
                    </button>
                </div>
            </div>
            <div v-if="error" role="alert"
                 class="mt-5 rounded-md bg-red-50 dark:bg-red-950/40 p-3 text-sm text-red-700 dark:text-red-300">
                {{ error }}
            </div>
            <form v-if="selected" @submit.prevent="submit" class="mt-6 space-y-5">
                <div v-for="input in selected.formLayout" :key="input.id">
                    <label v-if="inputType(input) === 'checkbox'" class="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-300">
                        <input v-model="model[input.id]" type="checkbox"
                               class="rounded border-gray-300 text-indigo-600 focus:ring-indigo-500">
                        {{ input.label || humanize(input.id) }}
                    </label>
                    <template v-else>
                        <label :for="fieldId(input)" class="block text-sm font-medium text-gray-700 dark:text-gray-300">
                            {{ input.label || humanize(input.id) }}
                        </label>
                        <textarea v-if="inputType(input) === 'textarea'" :id="fieldId(input)" v-model="model[input.id]"
                                  :placeholder="input.placeholder" :required="input.required" :autocomplete="input.autocomplete"
                                  rows="4" :class="inputClass"></textarea>
                        <select v-else-if="inputType(input) === 'select'" :id="fieldId(input)" v-model="model[input.id]"
                                :required="input.required" :class="inputClass">
                            <option v-if="input.placeholder" value="">{{ input.placeholder }}</option>
                            <option v-for="option in optionsOf(input)" :key="option.value" :value="option.value">{{ option.label }}</option>
                        </select>
                        <input v-else :id="fieldId(input)" v-model="model[input.id]" :type="inputType(input)"
                               :placeholder="input.placeholder" :required="input.required" :autocomplete="autocompleteOf(input)"
                               :class="inputClass">
                        <p v-if="input.help" class="mt-1 text-xs text-gray-500 dark:text-gray-400">{{ input.help }}</p>
                    </template>
                </div>
                <button type="submit" :disabled="loading"
                        class="w-full rounded-md bg-indigo-600 px-4 py-2 text-sm font-semibold text-white
                               hover:bg-indigo-700 disabled:cursor-not-allowed disabled:opacity-60">
                    {{ loading ? 'Signing In…' : 'Sign In' }}
                </button>
            </form>
            <div v-if="oauthProviders.length" class="mt-6">
                <div class="relative"><div class="absolute inset-0 flex items-center"><div class="w-full border-t border-gray-300 dark:border-gray-700"></div></div>
                    <div class="relative flex justify-center text-sm"><span class="bg-white dark:bg-gray-900 px-2 text-gray-500">Or continue with</span></div>
                </div>
                <div class="mt-5 grid grid-cols-2 gap-3">
                    <a v-for="provider in oauthProviders" :key="provider.name" :href="oauthUrl(provider)"
                       class="flex items-center justify-center gap-2 rounded-md border border-gray-300 dark:border-gray-700 px-3 py-2 text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-800">
                        <img v-if="provider.icon?.uri" :src="provider.icon.uri" class="size-5" alt="">
                        {{ labelOf(provider) }}
                    </a>
                </div>
            </div>
            <p v-if="!formProviders.length && !oauthProviders.length" class="mt-6 text-center text-sm text-gray-500">No authentication providers configured.</p>
        </div>
    `,
    setup(_, { emit }) {
        const client = inject('client')
        const auth = useAuth()
        const info = globalThis.AuthInfo || {}
        const providers = info.authProviders || []
        const formProviders = providers.filter(x => x.formLayout?.length)
        const oauthProviders = providers.filter(x => !x.formLayout?.length && x.navItem?.href)
        const selected = ref(formProviders[0] || null)
        const model = ref({})
        const loading = ref(false)
        const error = ref('')
        const inputClass = 'mt-1 block w-full rounded-md border border-gray-300 dark:border-gray-700 bg-white dark:bg-gray-950 px-3 py-2 text-gray-900 dark:text-gray-100 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none'

        const humanize = value => String(value || '').replace(/([a-z0-9])([A-Z])/g, '$1 $2')
        const labelOf = provider => provider.label || humanize(provider.name)
        const fieldId = input => `signin-${selected.value?.name}-${input.id}`
        const inputType = input => String(input.type || 'text').toLowerCase()
        const autocompleteOf = input => input.autocomplete || (inputType(input) === 'password' ? 'current-password'
            : String(input.id).toLowerCase() === 'username' ? 'username' : undefined)
        const optionsOf = input => input.allowableEntries?.map(x => ({ value:x.key, label:x.value }))
            || input.allowableValues?.map(x => ({ value:x, label:x })) || []
        const valueOf = name => {
            const key = Object.keys(model.value).find(x => x.toLowerCase() === name.toLowerCase())
            return key ? model.value[key] : undefined
        }
        function reset(provider) {
            model.value = Object.fromEntries((provider?.formLayout || []).map(x => [x.id, inputType(x) === 'checkbox' ? false : '']))
        }
        function select(provider) {
            selected.value = provider
            error.value = ''
            reset(provider)
        }
        reset(selected.value)

        function oauthUrl(provider) {
            const href = provider.navItem.href
            const separator = href.includes('?') ? '&' : '?'
            return href + separator + 'continue=' + encodeURIComponent(location.href)
        }

        async function submit() {
            const provider = selected.value
            if (!provider) return
            loading.value = true
            error.value = ''
            try {
                let request = new Authenticate({ provider: provider.name, ...model.value })
                if (provider.name === 'authsecret') {
                    client.headers.set('authsecret', valueOf('authsecret'))
                    request = new Authenticate()
                } else if (provider.name === 'basic') {
                    client.setCredentials(valueOf('userName'), valueOf('password'))
                    request = new Authenticate()
                } else if (provider.type === 'Bearer' || provider.name === 'jwt' || provider.name === 'apikey') {
                    client.bearerToken = valueOf('bearerToken')
                    request = new Authenticate()
                }
                const response = await client.post(request)
                auth.signIn(response)
                emit('login', response)
            } catch (e) {
                error.value = e?.responseStatus?.message || e?.message || 'Sign in failed'
            } finally {
                loading.value = false
            }
        }

        return {
            formProviders, oauthProviders, selected, model, loading, error, inputClass,
            humanize, labelOf, fieldId, inputType, autocompleteOf, optionsOf, select, oauthUrl, submit,
        }
    },
}

const template = `
<div v-if="authInfo" class="relative inline-block text-left">
    <!-- Button -->
    <button type="button" @click="onClick" :title="user ? (user.displayName || user.userName || 'Account') : 'Sign In'"
            class="flex items-center justify-center rounded-full p-1.5 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-800 focus:outline-none transition-colors">
        <!-- Signed in avatar -->
        <template v-if="user">
            <img v-if="user.profileUrl" :src="user.profileUrl" alt="Avatar" class="w-6 h-6 rounded-full object-cover" />
            <div v-else class="w-6 h-6 rounded-full bg-indigo-600 text-white flex items-center justify-center text-[10px] font-semibold uppercase">
                {{ initials }}
            </div>
        </template>
        <!-- Anonymous avatar -->
        <svg v-else class="w-5 h-5" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">
            <path d="M0 0h24v24H0z" fill="none" />
            <g fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5">
                <path d="M7 15a3 3 0 1 0 0 6a3 3 0 0 0 0-6m10 0a3 3 0 1 0 0 6a3 3 0 0 0 0-6m-3 2h-4m12-4c-2.457-1.228-6.027-2-10-2s-7.543.772-10 2" />
                <path d="m19 11.5l-1.058-6.788c-.215-1.384-1.719-2.134-2.933-1.463l-.615.34a4.94 4.94 0 0 1-4.788 0l-.615-.34c-1.214-.671-2.718.08-2.933 1.463L5 11.5" />
            </g>
        </svg>
    </button>

    <!-- Signed-in User Menu Dropdown -->
    <div v-if="openMenu" class="fixed inset-0 z-30" @click="openMenu = false"></div>
    <div v-if="openMenu" class="absolute right-0 mt-2 w-48 z-40 rounded-lg shadow-lg py-1 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 text-xs">
        <div class="px-4 py-2 border-b border-gray-100 dark:border-gray-700">
            <p class="font-semibold text-gray-900 dark:text-gray-100 truncate">{{ user?.displayName || user?.userName }}</p>
            <p v-if="user?.email" class="text-gray-500 dark:text-gray-400 truncate">{{ user.email }}</p>
        </div>
        <a :href="logoutUrl" class="block w-full text-left px-4 py-2 text-rose-600 dark:text-rose-400 hover:bg-gray-100 dark:hover:bg-gray-700 font-medium transition-colors">
            Sign Out
        </a>
    </div>

    <!-- Sign In Modal -->
    <Teleport to="body">
        <ModalDialog v-if="openSignIn" @done="openSignIn = false" size-class="sm:max-w-md sm:w-full">
            <div class="p-4 bg-white dark:bg-gray-900 rounded-lg">
                <MetadataFreeSignIn @login="onLogin" />
            </div>
        </ModalDialog>
    </Teleport>
</div>
`

export const AvatarButton = {
    name: 'AvatarButton',
    components: { MetadataFreeSignIn, ModalDialog, Teleport },
    template,
    setup() {
        const client = inject('client', null) ?? new JsonServiceClient()
        provide('client', client)

        const authInfo = globalThis.AuthInfo
        const { user, isAuthenticated } = useAuth()
        const openMenu = ref(false)
        const openSignIn = ref(false)

        const initials = computed(() => {
            const u = user.value
            if (!u) return ''
            const name = u.displayName || u.userName || ''
            return name ? name.substring(0, 2) : '?'
        })

        const logoutUrl = computed(() => {
            const current = typeof location !== 'undefined' ? (location.pathname + location.search) : '/'
            return '/auth/logout?ReturnUrl=' + encodeURIComponent(current)
        })

        function onClick() {
            if (isAuthenticated.value || user.value) {
                openMenu.value = !openMenu.value
            } else {
                openSignIn.value = true
            }
        }

        function onLogin() {
            openSignIn.value = false
            location.reload()
        }

        return {
            authInfo,
            user,
            isAuthenticated,
            openMenu,
            openSignIn,
            initials,
            logoutUrl,
            onClick,
            onLogin,
        }
    },
}

export default AvatarButton
